create table if not exists waitlist_leads (id uuid primary key default gen_random_uuid(), email text not null, normalized_email text generated always as (lower(trim(email))) stored, first_name text not null, role text not null, coding_tool text not null, app_stage text not null, concerns text[] default '{}', guided_scan_interest text not null, payment_interest text not null, app_description text, message text, consent boolean not null, referral_source text, created_at timestamptz default now(), status text default 'New', internal_notes text);
create table if not exists profiles (id uuid primary key references auth.users(id), email text, display_name text, role text, created_at timestamptz default now());
create table if not exists projects (id uuid primary key default gen_random_uuid(), owner_id uuid references profiles(id), name text not null, framework text not null, database_type text not null, demo_condition text not null, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists scans (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id), scan_type text, status text, score int, started_at timestamptz, finished_at timestamptz, is_simulation boolean default true);
create table if not exists findings (id uuid primary key default gen_random_uuid(), project_id uuid references projects(id), scan_id uuid references scans(id), rule_id text, title text, severity text, status text, confidence text, source_type text, file_path text, line_number int, table_name text, code_sample text, explanation text, possible_effect text, suggested_fix text, verification_method text, placeholder_id text, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists finding_events (id uuid primary key default gen_random_uuid(), finding_id uuid references findings(id), event_type text, previous_status text, new_status text, reason text, created_by uuid, created_at timestamptz default now());
create table if not exists placeholder_registry (id uuid primary key default gen_random_uuid(), placeholder_code text unique, feature text, prototype_behavior text, real_replacement text, data_needed text, security_review_required boolean, difficulty text, replacement_status text default 'Placeholder', owner text, notes text, updated_at timestamptz default now());
